    28	function getThumbnailAndImageURIs(transaction: OnyxEntry<Transaction>, receiptPath: ReceiptSource | null = null, receiptFileName: string | null = null): ThumbnailAndImageURI {
    29	    if (TransactionUtils.isFetchingWaypointsFromServer(transaction)) {
