    35	    const path = errors?.source ?? transaction?.receipt?.source ?? receiptPath ?? '';
    36	    // filename of uploaded image or last part of remote URI
    37	    const filename = errors?.filename ?? transaction?.filename ?? receiptFileName ?? '';
    38	    const isReceiptImage = Str.isImage(filename);
    39	    const hasEReceipt = !TransactionUtils.hasReceiptSource(transaction) && transaction?.hasEReceipt;
